export const mock: Provider = {
  name: "mock",
  async call(prompt, cfg, timeoutMs, info) {
    const delay = Number(cfg.mock_delay_ms ?? 0);
    if (delay > 0) {
      if (delay > timeoutMs) {
        await new Promise((r) => setTimeout(r, timeoutMs));
        return [null, "timeout (mock)"];
      }
      await new Promise((r) => setTimeout(r, delay));
    }
    const ratio = Number(cfg.mock_fail_ratio ?? 0);
    if (ratio > 0 && Math.random() < ratio) return [null, "mock failure"];
    let score = Number(cfg.mock_score ?? 0.1);
    const hdr = typeof cfg.mock_header === "string" ? info?.headers.get(cfg.mock_header) : null;
    if (hdr === "fail") return [null, "mock failure (header)"];
    if (hdr !== null && hdr !== undefined && Number.isFinite(Number(hdr))) score = Number(hdr);
    const answers: Answers = {};
    for (const name of Object.keys(prompt.questions)) answers[name] = score;
    return [answers, null];
  },
};

export const PROVIDERS: Record<string, Provider> = { jev, "openai-compat": openaiCompat, backend, mock };

export function load(name: string): Provider {
  const p = PROVIDERS[name];
  if (!p) throw new Error(`unknown provider: ${name}`);
  return p;
}

/** Add this verdict's points and block the subject when it crosses block_at.
 *  Only judged verdicts count (not L1). Never throws. Returns the points, or null. */
export async function repRecord(ctx: RepCtx, v: Verdict): Promise<number | null> {
  const c = repCfg(ctx);
  if (!c || v.source === "l1") return null;
  const [r, at] = c;
  const id = idOf(ctx);
  const store = ctx.subject?.store;
  if (!id || !store) return null;
  let w = 0;
  if (v.verdict === "malicious") w = r.malicious ?? 3;
  else if (v.verdict === "suspicious") w = r.suspicious ?? 1;
  if (!(w > 0)) return null;
  try {
    const win = r.window_s ?? 600;
    const now = ctx.clock ? ctx.clock() : 0;
    const b = Math.floor(now / win);
    const key = REP_PREFIX + id + ":b:";
    const cur = (await incrBy(store, key + b, w, win * 2)) || 0;
    const prev = Number(await store.get(key + (b - 1))) || 0;
    const p = cur + prev * (1 - (now - b * win) / win);
    if (p >= at) {
      const ttl = r.block_ttl ?? 600;
      await store.set(REP_PREFIX + id + ":until", now + ttl, ttl);
    }
    return p;
  } catch {
    return null;
  }
}

export function entry(id: string, v: Verdict, now: number): Entry {
  return {
    at: Number.isFinite(now) ? now : 0,
    subject: String(id ?? ""),
    verdict: v.verdict,
    score: v.score,
    source: v.source,
    reason: v.reason,
    fingerprint: v.fingerprint,
  };
}

export interface DenoOptions extends Options {
  /** Where allowed requests go: its origin plus the request's path and query. */
  upstream: string;
  /** Deno KV (`await Deno.openKv()`): backs the cache, the breaker / adaptive
   *  state and the subject store unless `cache`, `state` or `subjectStore`
   *  is given. Memory per isolate without it. */
  kv?: DenoKvLike;
}

/** The request as the runtime should see it: the peer appended to X-Forwarded-For. */
function withPeer(request: Request, info?: DenoServeInfoLike): Request {
  const peer = info?.remoteAddr?.hostname;
  if (!peer) return request;
  const headers = new Headers(request.headers);
  const xff = headers.get("x-forwarded-for");
  headers.set("x-forwarded-for", xff ? xff + ", " + peer : peer);
  return new Request(request, { headers });
}

export function createRuntime(opts: Options): Runtime {
  const config = core.defaults.merge(core.defaults.config, opts.config ?? {});
  const [ok, err] = core.defaults.validate(config);
  if (!ok) throw new Error("jev-edge config: " + err);
  const rules = ((opts.rules ?? config.rules) as RuleSpec[]).map(resolveRule);
  const provider = opts.provider ?? loadProvider(config.jev.provider ?? "jev");
  const clock = () => Date.now() / 1000;
  const cache: Store = isKV(opts.cache) ? kvStore(opts.cache) : (opts.cache as Store | undefined) ?? memoryStore(clock);
  const subjectStore: Store = isKV(opts.subjectStore) ? kvStore(opts.subjectStore, "jev:") : (opts.subjectStore as Store | undefined) ?? memoryStore(clock);
  let state: Store;
  let breaker: BreakerLike;
  let adaptive: AdaptiveLike;
  if (isStub(opts.state)) {
    // One hop per operation: the Durable Object runs the same Breaker and
    // Adaptive classes against its own storage, so the read-modify-write is
    // atomic there instead of three or four round trips from here.
    state = durableStore(opts.state);
    breaker = durableBreaker(opts.state, config.breaker);
    adaptive = durableAdaptive(opts.state, config.jev);
  } else {
    state = (opts.state as Store | undefined) ?? memoryStore(clock);
    breaker = new core.breaker.Breaker(state, clock, config.breaker);
    adaptive = new Adaptive(state, config.jev);
  }
  return { config, rules, provider, cache, state, subjectStore, breaker, adaptive, opts };
}

export interface Config {
  jev: JevConfig;
  rules: string[];
  policy: Policy;
  /** fp_prefix_bytes: since 0.3.1 only bounds sampled/logged text; the fingerprint always covers the whole normalized text. */
  cache: { fp_ttl: number; rep_ttl: number; fp_prefix_bytes: number };
  /**
   * How adapters that sit behind another proxy find the client address in
   * X-Forwarded-For. Proxies APPEND to the header, so the client's own value
   * is on the left and the one your proxy added is on the right:
   * `trusted_hops: 1` takes the last element, 2 the one before it (a load
   * balancer in front of the gateway), and so on. Never the first element:
   * that is whatever the client typed.
   */
  client_ip: { trusted_hops: number };
  async: { enabled: boolean; max_async: number; rep_block_after: number; rep_block_ttl: number };
  subject: {
    enabled: boolean; from: "ip" | "header" | "cookie"; name: string | null; salt: string | null; hashed: boolean;
    history_ttl: number; max_entries: number;
    /** see core/defaults.lua subject.reputation; block_at 0 is off */
    reputation: { block_at: number; window_s: number; block_ttl: number; suspicious: number; malicious: number };
  };
  sampling: { enabled: boolean; rate: number; min_verdict: "safe" | "suspicious" | "malicious"; max_samples: number; ttl: number; text_bytes: number; log: boolean };
  feedback: FeedbackConfig;
  breaker: BreakerConfig;
}

