export function memoryStore(clock: () => number = () => Date.now() / 1000): Store {
  const m = new Map<string, Entry>();
  return {
    get: (k) => {
      const e = m.get(k);
      if (!e) return undefined;
      if (e.exp && e.exp <= clock()) {
        m.delete(k);
        return undefined;
      }
      return e.v;
    },
    set: (k, v, ttl) => {
      if (v === null || v === undefined) m.delete(k);
      else m.set(k, { v, exp: ttl > 0 ? clock() + ttl : 0 });
    },
    // synchronous, so atomic within the isolate; the ttl applies on creation only
    incr: (k, by, ttl) => {
      const e = m.get(k);
      const live = e !== undefined && !(e.exp && e.exp <= clock());
      const n = (live ? Number(e.v) || 0 : 0) + by;
      m.set(k, { v: n, exp: live ? e.exp : ttl > 0 ? clock() + ttl : 0 });
      return n;
    },
    expire: (k, ttl) => {
      const e = m.get(k);
      if (e && !(e.exp && e.exp <= clock())) e.exp = ttl > 0 ? clock() + ttl : 0;
    },
  };
}

/**
 * Highest answer wins. Lua iterates `pairs` in undefined order, so on an exact
 * tie the winning template name is unspecified on both implementations; the
 * score is not.
 */
/** Returns [score, top template, count of numeric answers]; a count of 0 means
 *  the provider answered nothing usable -- an error, not a safe score. */
export function reduce(answers: Answers | null | undefined): [number, string, number] {
  let best = 0;
  let bestName = "";
  let n = 0;
  for (const [name, raw] of Object.entries(answers ?? {})) {
    if (typeof raw !== "number" && typeof raw !== "string") continue; // Lua tonumber(table/bool) -> nil
    if (typeof raw === "string" && raw.trim() === "") continue; // Lua tonumber("") -> nil; Number("") is 0
    const p = typeof raw === "number" ? raw : Number(raw);
    if (Number.isNaN(p)) continue;
    n++;
    if (p > best) {
      best = p;
      bestName = name;
    }
  }
  if (best > 1) best = 1;
  return [best, bestName, n];
}

