/**
 * true when a reply object is a copy of an answer planted in the judged text:
 * the same values for the asked questions as a JSON object in the input. A
 * model that repeats the input's own verdict was steered by it, which is what
 * an injection is; the caller scores it as one. Port of echoes_input in
 * providers/openai_compat.lua; compared on parsed values, not on spelling.
 */
export function echoesInput(content: string, text: string | undefined, wanted: string[]): boolean {
  if (typeof text !== "string" || !text.includes("{")) return false;
  const names = [...wanted].sort();
  const planted = new Set<string>();
  for (const o of objectsOf(text)) {
    const sig = answerSig(o, names);
    if (sig) planted.add(sig);
  }
  if (planted.size === 0) return false;
  return objectsOf(content).some((o) => {
    const sig = answerSig(o, names);
    return sig !== undefined && planted.has(sig);
  });
}

function formValues(body: string, out: string[]): void {
  // Lua: body:gmatch("([^&=]+)=([^&]*)")
  const re = /([^&=]+)=([^&]*)/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(body)) !== null) out.push(formDecode(m[2]));
}

const MAX_PARTS = 100;
function multipartValues(body: string, contentType: string, out: string[]): void {
  const bm = /boundary="([^"]+)"/i.exec(contentType) ?? /boundary=([^;\s,]+)/i.exec(contentType);
  if (!bm) return;
  const delim = "--" + bm[1];
  let pos = body.indexOf(delim);
  let parts = 0;
  while (pos !== -1 && parts < MAX_PARTS) {
    const after = pos + delim.length;
    if (body.slice(after, after + 2) === "--") break; // closing delimiter
    const next = body.indexOf(delim, after);
    let part = body.slice(after, next === -1 ? body.length : next);
    part = part.replace(/^\r?\n/, "").replace(/\r?\n$/, "");
    const hm = /\r?\n\r?\n/.exec(part);
    if (hm) {
      const head = asciiLower(part.slice(0, hm.index));
      const value = part.slice(hm.index + hm[0].length);
      const hasFile = /filename\*?=/.test(head);
      const pct = /content-type:[ \t\n\v\f\r]*([^\r\n;]+)/.exec(head)?.[1] ?? "";
      if ((!hasFile || pct.startsWith("text/") || pct.includes("json")) && isText(value)) out.push(value);
    }
    parts++;
    pos = next;
  }
}

