  methods?: Record<string, boolean>;
  /** Allow list (the pre-0.4 behaviour); without it, skip_content_types applies. */
  content_types?: string[];
  /** Media types never judged; everything else is read and the body decides the format. */
  skip_content_types?: string[];
  min_body_bytes?: number;
  max_body_bytes?: number;
  max_judge_bytes?: number;
  /** Judge text over max_judge_bytes in up to this many chunks (default 1: one window). */
  max_judge_chunks?: number;
  text_fields: string[];
  min_text_chars?: number;
  always_suspect?: string[];
  templates: string[];
  deployment_context?: string;
}

export interface Req {
  method?: string;
  path?: string;
  /** A repeated header may arrive as a list (Lua's ngx.req.get_headers does this). */
  headers?: Record<string, string | string[] | undefined>;
  body?: string | null;
  body_size?: number;
  client_ip?: string;
  /** Past max_body_bytes: the first bytes and the last bytes (not overlapping) the adapter kept. */
  body_head?: string | null;
  body_tail?: string | null;
  /** true when the adapter decoded the Content-Encoding and `body` is the decoded body. */
  decoded?: boolean;
}

export interface CacheLike {
  get(key: string): unknown | Promise<unknown>;
  set?(key: string, value: unknown, ttl: number): void | Promise<void>;
}

export interface DOStubLike {
  fetch(input: string | Request, init?: RequestInit): Promise<Response>;
}

function caller(stub: DOStubLike) {
  return async (path: string, payload: unknown): Promise<{ value?: unknown; ok?: boolean }> => {
    const res = await stub.fetch("https://jev-state" + path, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error(`jev-state ${path}: http ${res.status}`);
    return (await res.json()) as { value?: unknown; ok?: boolean };
  };
}

/** The plain Store interface over a JevState stub: two hops per read-modify-write, one (atomic) per incr. */
export function durableStore(stub: DOStubLike): Store {
  const call = caller(stub);
  return {
    get: async (k) => (await call("/get", { key: k })).value ?? undefined,
    set: async (k, v, ttl) => {
      await call("/set", { key: k, value: v ?? null, ttl });
    },
    incr: async (k, by, ttl) => Number((await call("/incr", { key: k, by, ttl })).value),
    expire: async (k, ttl) => {
      await call("/expire", { key: k, ttl });
    },
  };
}

export const openaiCompat: Provider = {
  name: "openai-compat",
  async call(prompt, cfg, timeoutMs) {
    const endpoint = (cfg.endpoint ?? "http://127.0.0.1:11434/v1").replace(/\/+$/, "");
    const nonce = newNonce();
    const body = JSON.stringify({
      model: cfg.model ?? "gpt-4o-mini",
      temperature: 0,
      max_tokens: 200,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: openaiSystemPrompt(prompt.questions, nonce) },
        { role: "user", content: openaiUserMessage(prompt.text, nonce) },
      ],
    });
    const headers: Record<string, string> = { "Content-Type": "application/json" };
    if (cfg.api_key) headers.Authorization = "Bearer " + cfg.api_key;
    let content: string;
    try {
      content = await fetchWithin(endpoint + "/chat/completions", { method: "POST", headers, body }, timeoutMs, async (res) => {
        if (res.status !== 200) throw new HttpStatus(res.status);
        try {
          const d = (await res.json()) as { choices?: { message?: { content?: string } }[] };
          return d.choices?.[0]?.message?.content ?? "";
        } catch (e) {
          if (e instanceof Error && e.name === "AbortError") throw e;
          throw new Error("malformed response");
        }
      });
    } catch (e) {
      if (e instanceof HttpStatus) return [null, "openai-compat http " + e.status];
      if (e instanceof Error && e.message === "malformed response") return [null, "openai-compat: malformed response"];
      return [null, errorString(e, timeoutMs)];
    }
    if (typeof content !== "string") return [null, "openai-compat: no content"];
    const wanted = Object.keys(prompt.questions);
    // a reply that copies an answer planted in the input: the judge was
    // steered, so every asked question scores 1 (an error would fail open,
    // which is exactly what the planted answer is for)
    if (echoesInput(content, prompt.text, wanted)) {
      console.warn("jev-edge: openai-compat judge echoed an answer planted in the input");
      return [Object.fromEntries(wanted.map((n) => [n, 1])), null];
    }
    return parseOpenaiContent(content, wanted);
  },
};

