/** Lua's tonumber(h, 16) + string.char: bytes, so %C3%BC is two bytes not one char. */
function formDecode(v: string): string {
  const bytes: number[] = [];
  const s = v.replace(/\+/g, " ");
  const b = enc.encode(s);
  for (let i = 0; i < b.length; i++) {
    if (b[i] === 0x25 && i + 2 < b.length) {
      const hex = String.fromCharCode(b[i + 1], b[i + 2]);
      if (/^[0-9a-fA-F]{2}$/.test(hex)) {
        bytes.push(parseInt(hex, 16));
        i += 2;
        continue;
      }
    }
    bytes.push(b[i]);
  }
  return dec.decode(new Uint8Array(bytes));
}

// ---------------------------------------------------------------------------
// Format detection (port of normalize.extract in core/normalize.lua): the
// body decides, the Content-Type is a hint. JSON when it parses as JSON, form
// or multipart when declared (or form-shaped with no header), text when it
// reads as text, "binary" otherwise.
// ---------------------------------------------------------------------------

/** Lua is_text: no NUL, control bytes other than \t \n \r under 1% of the bytes. */
export function isText(s: string): boolean {
  if (s.includes("\0")) return false;
  const ctl = (s.match(/[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]/g) ?? []).length;
  return ctl * 100 <= byteLength(s);
}

export function pathMatches(s: string, patterns: string[] | undefined): string | null {
  for (const p of patterns ?? []) {
    if (luaPatternToRegExp(p).test(s)) return p;
  }
  return null;
}

let warned = false;
const badPatterns = new Set<string>();
function textMatches(s: string, patterns: string[] | undefined, ctx: RulesCtx | undefined): [string, number?, number?] | null {
  if (!patterns || patterns.length === 0) return null;
  const reFind = ctx?.re_find;
  if (!reFind) {
    if (!warned && ctx?.log) {
      warned = true;
      ctx.log("warn", "jev-edge: ctx.re_find not provided; always_suspect prefilter disabled");
    }
    return null;
  }
  for (const p of patterns) {
    try {
      const hit = reFind(s, p);
      if (Array.isArray(hit)) return [p, hit[0], hit[1]];
      if (hit) return [p];
    } catch (e) {
      // a pattern the engine rejects is skipped, like pcall in Lua, but an
      // operator should hear about it once instead of losing the prefilter silently
      if (!badPatterns.has(p)) {
        badPatterns.add(p);
        const msg = `jev-edge: always_suspect pattern ${JSON.stringify(p)} does not compile and is skipped: ${e instanceof Error ? e.message : String(e)}`;
        if (ctx?.log) ctx.log("warn", msg);
        else console.warn(msg);
      }
    }
  }
  return null;
}

/** History for the request path: the ring when the store has `incr`, else the
 *  one-list layout (custom stores with only get/set keep working). */
export async function loadHistory(store: Store, id: string, maxEntries = 20): Promise<unknown> {
  if (typeof store.incr === "function") return ringLoad(store, id, maxEntries);
  return store.get(key(id));
}

/** The write behind `record`: ring append, or the list read-then-write on a
 *  store without `incr` (which can lose an entry to a concurrent append). */
export async function appendHistory(store: Store, id: string, e: Entry, maxEntries = 20, ttl = 3600): Promise<void> {
  if (typeof store.incr === "function") {
    await ringAppend(store, id, e, maxEntries, ttl);
    return;
  }
  await store.set(key(id), append(await store.get(key(id)), e, maxEntries), ttl);
}

/** Cookie header -> one cookie's value, or null. */
export function cookieValue(header: string | null | undefined, name: string): string | null {
  if (!header) return null;
  for (const part of header.split(";")) {
    const i = part.indexOf("=");
    if (i < 0) continue;
    if (part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return null;
}

