/** The subject id for this request, or null when there is none. */
export function idOf(ctx: { subject?: SubjectCtx }): string | null {
  const s = ctx.subject;
  if (!s || typeof s !== "object") return null;
  return typeof s.id === "string" && s.id !== "" ? s.id : null;
}

/** Hand one entry to the sink, if there is a subject and a sink. Returns the
 *  entry recorded, or null. Never throws, and never awaits the sink. */
export function record(ctx: { subject?: SubjectCtx; clock?: () => number }, v: Verdict): Entry | null {
  const id = idOf(ctx);
  if (!id) return null;
  const sink = ctx.subject!.record;
  if (typeof sink !== "function") return null;
  const e = entry(id, v, ctx.clock ? ctx.clock() : 0);
  try {
    const p = sink(e);
    if (p && typeof (p as Promise<void>).catch === "function") (p as Promise<void>).catch(() => {});
  } catch {
    /* a trajectory write must never be able to fail a request */
  }
  return e;
}

// Lambda@Edge (CloudFront viewer-request or origin-request) on the same
// runtime. The one AWS entry point that sees the body: with "Include Body"
// on the trigger, CloudFront hands it over base64-encoded, truncated at 40 KB
// (viewer-request) or 1 MB (origin-request) with `bodyTruncated` set. A
// truncated body is passed at L1 as "body too large", the same fail-open the
// other adapters apply, and the full body still reaches the origin.
//
//   import { lambdaEdgeHandler } from "@jev-edge/js/aws";
//   export const handler = lambdaEdgeHandler({ config: { ... } });
//
// Lambda@Edge has no environment variables, no VPC and no KV: the cache,
// breaker and adaptive timeout are per execution environment (memory) unless
// you pass Store implementations (DynamoDB Global Tables is the usual
// choice; it costs a round trip per lookup). Read the API key from Secrets
// Manager at cold start and pass it in `config.jev.api_key`.
import { createRuntime, evaluate, markTruncated, type Options, type Runtime } from "./runtime.js";
import { headers as verdictHeaders, newVerdict, ERROR, SRC_ADAPTER } from "./core/verdict.js";

export function resolve(spec: RuleSpec): Rule {
  // A string is the same as `{ extends: "<id>" }`: the loaded module is
  // copied, never handed back, so callers cannot mutate the shared table,
  // and the same defaults apply to both forms.
  if (typeof spec === "string") spec = { extends: spec } as RuleSpec & object;
  if (typeof spec !== "object" || spec === null) throw new Error("rule spec must be a string or a table");
  const base: Partial<Rule> = spec.extends ? load(spec.extends) : {};
  const { extends: _ext, ...over } = spec;
  const out = { ...base, ...over } as Rule;
  if (!out.id) throw new Error("rule needs an id");
  if (!Array.isArray(out.watch_paths)) throw new Error(`rule ${out.id} needs watch_paths`);
  // watch_paths are Lua patterns; a malformed one raises on every request.
  out.watch_paths.forEach((p, i) => {
    if (typeof p !== "string") throw new Error(`rule ${out.id}: watch_paths[${i + 1}] must be a string`);
    const perr = patternError(p);
    if (perr) throw new Error(`rule ${out.id}: watch_paths[${i + 1}] ${perr}`);
  });
  out.text_fields ??= ["messages[*].content", "prompt", "input", "query", "text"];
  out.templates ??= ["injection"];
  return out;
}

